pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(end < v.len(), "end must be within bounds");

    let mut max_val = v[0];
    let mut max_idx = 0usize;

    for i in 1..=end {
        let x = v[i];
        if x > max_val {
            max_val = x;
            max_idx = i;
        }
    }

    (max_val, max_idx)
}

pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(start < v.len(), "start must be within bounds");

    let mut min_val = v[start];
    let mut min_idx = start;

    for i in (start + 1)..v.len() {
        let x = v[i];
        if x < min_val {
            min_val = x;
            min_idx = i;
        }
    }

    (min_val, min_idx)
}

pub fn barrier(v: &[i32], p: usize) -> bool {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(p < v.len(), "p must be within bounds");

    // If there's no element on the right side, the condition is vacuously true.
    if p + 1 >= v.len() {
        return true;
    }

    let (max_left, _idx_left) = find_max_in_prefix(v, p);
    let (min_right, _idx_right) = find_min_in_suffix(v, p + 1);

    max_left < min_right
}

